using System;using System.Collections.Generic;using BepInEx.Logging;using Jotunn.Entities;using Jotunn.Managers;using Magenheim.Core;using UnityEngine;namespace Magenheim.Runtime;
internal sealed class DeepFractureCreatureRegistrar:IDisposable{
 internal const string AnnoyanceWispPrefix="Magenheim_AnnoyanceWisp_",GeodeCrawlerPrefix="Magenheim_GeodeCrawler_",ShardlingPrefix="Magenheim_Shardling_",CrystalParasitePrefix="Magenheim_CrystalParasite_",CrystalRevenantPrefix="Magenheim_CrystalRevenant_",FacetSentryPrefix="Magenheim_FacetSentry_",StoneSentinelPrefix="Magenheim_StoneSentinel_",CrystalHoundPrefix="Magenheim_CrystalHound_",BurrowerPrefix="Magenheim_Burrower_",StoneGuardianPrefix="Magenheim_StoneGuardian_",CrystalGolemPrefix="Magenheim_CrystalGolem_",ObeliskWardenPrefix="Magenheim_ObeliskWarden_",DeepColossusPrefix="Magenheim_DeepColossus_";
 private readonly ManualLogSource _log;private bool _subscribed,_registered;internal DeepFractureCreatureRegistrar(ManualLogSource log)=>_log=log??throw new ArgumentNullException(nameof(log));internal void Register(){if(_subscribed||_registered)return;PrefabManager.OnVanillaPrefabsAvailable+=RegisterContent;_subscribed=true;}
 private void RegisterContent(){if(_registered)return;try{// "Wisp" is an ambient light prop with no Character/BaseAI, so it could never satisfy the
 // chassis guard below; FrostWisp is the Deep North flying wisp and the only wisp-family
 // creature in the build. Because this array is built eagerly, a bad first source used to
 // cost every Deep Fracture variant, not just the Annoyance Wisp.
 var src=new[]{S("FrostWisp"),S("Tick"),S("Greydwarf"),S("Draugr"),S("DvergerMage"),S("StoneGolem"),S("Fenring"),S("Seeker")};var r=new List<string>();foreach(ElementalAlignment a in Enum.GetValues(typeof(ElementalAlignment))){r.Add(R(src[0],a,AnnoyanceWispPrefix,"Annoyance Wisp",34,5.5f,2.5f,(p,e)=>{DeepFractureCreatureVisuals.ApplyAnnoyanceWisp(p,e);DeepFractureLegacyCoreBinder.BindAnnoyanceWisp(p);}));r.Add(R(src[1],a,GeodeCrawlerPrefix,"Geode Crawler",72,4,1.8f,(p,e)=>{DeepFractureCreatureVisuals.ApplyGeodeCrawler(p,e);DeepFractureLegacyCoreBinder.BindGeodeCrawler(p);}));r.Add(R(src[2],a,ShardlingPrefix,"Shardling",48,6.2f,2.8f,(p,e)=>{DeepFractureCreatureVisuals.ApplyShardling(p,e);DeepFractureLegacyCoreBinder.BindShardling(p);}));r.Add(R(src[2],a,CrystalParasitePrefix,"Crystal Parasite",58,3.8f,1.6f,(p,e)=>{DeepFractureCreatureVisuals.ApplyCrystalParasite(p,e);DeepFractureLegacyCoreBinder.BindCrystalParasite(p);}));r.Add(R(src[3],a,CrystalRevenantPrefix,"Crystal Revenant",118,4.6f,2.1f,(p,e)=>{DeepFractureCreatureVisuals.ApplyCrystalRevenant(p,e);DeepFractureLegacyCoreBinder.BindCrystalRevenant(p);StripHumanoidEquipment(p,"Crystal Revenant");}));r.Add(R(src[4],a,FacetSentryPrefix,"Facet Sentry",92,0,0,(p,e)=>{DeepFractureCreatureVisuals.ApplyFacetSentry(p,e);DeepFractureLegacyCoreBinder.BindFacetSentry(p);ConstrainFacetSentry(p);}));r.Add(R(src[5],a,StoneSentinelPrefix,"Stone Sentinel",260,3.1f,1.25f,(p,e)=>{DeepFractureCreatureVisuals.ApplyStoneSentinel(p,e);DeepFractureLegacyCoreBinder.BindStoneSentinel(p);ConfigureStoneSentinel(p);}));r.Add(R(src[6],a,CrystalHoundPrefix,"Crystal Hound",96,7.2f,3.1f,(p,e)=>{DeepFractureCreatureVisuals.ApplyCrystalHound(p,e);DeepFractureLegacyCoreBinder.BindCrystalHound(p);}));r.Add(R(src[7],a,BurrowerPrefix,"Burrower",132,5.4f,2.2f,(p,e)=>{DeepFractureCreatureVisuals.ApplyBurrower(p,e);DeepFractureLegacyCoreBinder.BindBurrower(p);if(!p.GetComponent<DeepFractureBurrowerRuntime>())p.AddComponent<DeepFractureBurrowerRuntime>();}));r.Add(R(src[5],a,StoneGuardianPrefix,"Stone Guardian",440,2.7f,1.05f,(p,e)=>{DeepFractureCreatureVisuals.ApplyStoneGuardian(p,e);DeepFractureLegacyCoreBinder.BindStoneGuardian(p);ConfigureStoneGuardian(p);}));r.Add(R(src[5],a,CrystalGolemPrefix,"Crystal Golem",620,3.0f,1.15f,(p,e)=>{DeepFractureCrystalGolemVisual.Apply(p,e);ConfigureCrystalGolem(p);}));r.Add(R(src[5],a,ObeliskWardenPrefix,"Obelisk Warden",780,1.2f,.55f,(p,e)=>{DeepFractureObeliskWardenVisual.Apply(p,e);ConfigureObeliskWarden(p);}));r.Add(R(src[5],a,DeepColossusPrefix,"Deep Colossus",1200,2.2f,.8f,(p,e)=>{DeepFractureDeepColossusVisual.Apply(p,e);ConfigureDeepColossus(p);}));}_registered=true;_log.LogInfo($"Registered {r.Count} additive Deep Fracture creature variants: {string.Join(", ",r)}.");}catch(Exception e){_log.LogError($"Deep Fracture creature registration failed: {e}");throw;}finally{Dispose();}}
 private static void StripHumanoidEquipment(GameObject p,string chassis){var humanoid=p.GetComponent<Humanoid>()??throw new InvalidOperationException($"{chassis} host lost Humanoid authority required by its inherited combat animator.");humanoid.m_defaultItems=Array.Empty<GameObject>();humanoid.m_randomWeapon=Array.Empty<GameObject>();humanoid.m_randomArmor=Array.Empty<GameObject>();humanoid.m_randomSets=Array.Empty<Humanoid.ItemSet>();}
 private static void ConstrainFacetSentry(GameObject p){var ch=p.GetComponent<Character>()??throw new InvalidOperationException("Facet Sentry host lost Character authority.");ch.m_runSpeed=0f;ch.m_walkSpeed=0f;ch.m_flyFastSpeed=0f;ch.m_flySlowSpeed=0f;ch.m_acceleration=0f;var body=p.GetComponent<Rigidbody>();if(body!=null){body.constraints|=RigidbodyConstraints.FreezePositionX|RigidbodyConstraints.FreezePositionZ;body.linearVelocity=Vector3.zero;}StripHumanoidEquipment(p,"Facet Sentry");}
 private static void ConfigureStoneSentinel(GameObject p){var ch=p.GetComponent<Character>()??throw new InvalidOperationException("Stone Sentinel host lost Character authority.");ch.m_runSpeed=3.1f;ch.m_walkSpeed=1.25f;ch.m_acceleration=Mathf.Max(ch.m_acceleration,7.5f);ch.m_turnSpeed=Mathf.Max(ch.m_turnSpeed,170f);ch.m_jumpForce=0f;ch.m_jumpForceForward=0f;var ai=p.GetComponent<MonsterAI>()??throw new InvalidOperationException("Stone Sentinel StoneGolem host lost MonsterAI combat authority.");ai.m_alertRange=Mathf.Max(ai.m_alertRange,18f);ai.m_viewRange=Mathf.Max(ai.m_viewRange,24f);ai.m_viewAngle=Mathf.Max(ai.m_viewAngle,120f);ai.m_hearRange=Mathf.Max(ai.m_hearRange,16f);ai.m_circleTargetInterval=Mathf.Min(ai.m_circleTargetInterval,2.25f);ai.m_circleTargetDuration=Mathf.Min(ai.m_circleTargetDuration,2.5f);}
 private static void ConfigureStoneGuardian(GameObject p){var ch=p.GetComponent<Character>()??throw new InvalidOperationException("Stone Guardian host lost Character authority.");ch.m_runSpeed=2.35f;ch.m_walkSpeed=.9f;ch.m_acceleration=Mathf.Min(ch.m_acceleration,3.25f);ch.m_turnSpeed=Mathf.Min(ch.m_turnSpeed,85f);ch.m_jumpForce=0f;ch.m_jumpForceForward=0f;var ai=p.GetComponent<MonsterAI>()??throw new InvalidOperationException("Stone Guardian StoneGolem host lost MonsterAI combat authority.");ai.m_alertRange=Mathf.Min(ai.m_alertRange,14f);ai.m_viewRange=Mathf.Min(ai.m_viewRange,18f);ai.m_viewAngle=Mathf.Min(ai.m_viewAngle,90f);ai.m_hearRange=Mathf.Min(ai.m_hearRange,12f);ai.m_circleTargetInterval=Mathf.Max(ai.m_circleTargetInterval,5.5f);ai.m_circleTargetDuration=Mathf.Max(ai.m_circleTargetDuration,4f);ai.m_randomMoveInterval=Mathf.Max(ai.m_randomMoveInterval,8f);ai.m_randomMoveRange=Mathf.Min(ai.m_randomMoveRange,3f);}
 private static void ConfigureCrystalGolem(GameObject p){var ch=p.GetComponent<Character>()??throw new InvalidOperationException("Crystal Golem host lost Character authority.");ch.m_runSpeed=3f;ch.m_walkSpeed=1.15f;ch.m_acceleration=Mathf.Clamp(ch.m_acceleration,4.5f,6f);ch.m_turnSpeed=Mathf.Clamp(ch.m_turnSpeed,105f,135f);ch.m_jumpForce=0f;ch.m_jumpForceForward=0f;var ai=p.GetComponent<MonsterAI>()??throw new InvalidOperationException("Crystal Golem StoneGolem host lost MonsterAI combat authority.");ai.m_alertRange=Mathf.Max(ai.m_alertRange,20f);ai.m_viewRange=Mathf.Max(ai.m_viewRange,26f);ai.m_viewAngle=Mathf.Max(ai.m_viewAngle,105f);ai.m_hearRange=Mathf.Max(ai.m_hearRange,18f);ai.m_circleTargetInterval=Mathf.Clamp(ai.m_circleTargetInterval,3f,4f);ai.m_circleTargetDuration=Mathf.Clamp(ai.m_circleTargetDuration,2.5f,3.5f);ai.m_randomMoveInterval=Mathf.Max(ai.m_randomMoveInterval,6f);ai.m_randomMoveRange=Mathf.Min(ai.m_randomMoveRange,5f);}
 private static void ConfigureObeliskWarden(GameObject p){var ch=p.GetComponent<Character>()??throw new InvalidOperationException("Obelisk Warden host lost Character authority.");ch.m_runSpeed=1.2f;ch.m_walkSpeed=.55f;ch.m_acceleration=Mathf.Min(ch.m_acceleration,2.4f);ch.m_turnSpeed=Mathf.Min(ch.m_turnSpeed,65f);ch.m_jumpForce=0f;ch.m_jumpForceForward=0f;var ai=p.GetComponent<MonsterAI>()??throw new InvalidOperationException("Obelisk Warden StoneGolem host lost MonsterAI combat authority.");ai.m_alertRange=Mathf.Max(ai.m_alertRange,22f);ai.m_viewRange=Mathf.Max(ai.m_viewRange,28f);ai.m_viewAngle=Mathf.Max(ai.m_viewAngle,140f);ai.m_hearRange=Mathf.Max(ai.m_hearRange,20f);ai.m_circleTargetInterval=Mathf.Max(ai.m_circleTargetInterval,7f);ai.m_circleTargetDuration=Mathf.Max(ai.m_circleTargetDuration,5.5f);ai.m_randomMoveInterval=Mathf.Max(ai.m_randomMoveInterval,10f);ai.m_randomMoveRange=Mathf.Min(ai.m_randomMoveRange,2f);}
